import React, { useState, useEffect } from 'react';
import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Typography } from '@mui/material';
import axios from 'axios';

const ModificarPagosClientes = () => {
  const [historial, setHistorial] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchHistorial = async () => {
      try {
        const token = localStorage.getItem('token');
        const response = await axios.get('http://localhost:8000/api/historial_fondo/', {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });
        
        // Agrupar por cliente
        const historialPorCliente = response.data.reduce((acc, pago) => {
          if (!acc[pago.cliente_id]) {
            acc[pago.cliente_id] = {
              id: pago.cliente_id,
              nombre_cliente: pago.cliente_nombre,
              pagos: [],
              total_pagado: 0
            };
          }
          acc[pago.cliente_id].pagos.push(pago);
          acc[pago.cliente_id].total_pagado += pago.fondo;
          return acc;
        }, {});

        // Convertir a array y ordenar alfabéticamente
        const sortedData = Object.values(historialPorCliente).sort((a, b) => 
          a.nombre_cliente.localeCompare(b.nombre_cliente)
        );

        setHistorial(sortedData);
        setLoading(false);
      } catch (err) {
        setError(err.response?.data?.message || err.message);
        setLoading(false);
      }
    };

    fetchHistorial();
  }, []);

  if (loading) return <Typography>Cargando historial de pagos...</Typography>;
  if (error) return <Typography color="error">Error: {error}</Typography>;

  return (
    <TableContainer component={Paper} sx={{ marginTop: 2 }}>
      <Table aria-label="historial de fondos de clientes">
        <TableHead>
          <TableRow sx={{ backgroundColor: '#f5f5f5' }}>
            <TableCell sx={{ fontWeight: 'bold' }}>Cliente</TableCell>
            <TableCell sx={{ fontWeight: 'bold' }}>Total Fondo</TableCell>
            <TableCell sx={{ fontWeight: 'bold' }}>Cantidad de Pagos</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {historial.map((cliente) => (
            <React.Fragment key={cliente.id}>
              <TableRow>
                <TableCell>{cliente.nombre_cliente}</TableCell>
                <TableCell>${cliente.total_pagado.toFixed(2)}</TableCell>
                <TableCell>{cliente.pagos.length}</TableCell>
              </TableRow>
              {cliente.pagos.map((pago) => (
                <TableRow key={pago.id}>
                  <TableCell colSpan={3}>
                    <Typography variant="body2">
                      Fecha: {new Date(pago.fecha).toLocaleDateString()} - 
                      Monto: ${pago.fondo.toFixed(2)}
                    </Typography>
                  </TableCell>
                </TableRow>
              ))}
            </React.Fragment>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
};

export default ModificarPagosClientes;